def minXorSum(a, b):
    n = len(a)
    INF = 10 ** 18
    full = 1 << n
    dp = [INF] * full
    dp[0] = 0
    for mask in range(full):
        cur = dp[mask]
        if cur == INF:
            continue
        i = bin(mask).count("1")
        if i == n:
            continue
        for j in range(n):
            if not (mask >> j) & 1:
                nm = mask | (1 << j)
                c = cur + (a[i] ^ b[j])
                if c < dp[nm]:
                    dp[nm] = c
    return dp[full - 1]
